#![allow(dead_code)]
extern crate self as liquidbounce_behaviors;
extern crate self as horizon_client;
#[path="__POLICY_PATH__"]pub mod auto_tool;
#[path="__RENDER_PATH__"]pub mod silent_hotbar_render;
#[path="__ACTOR_PATH__"]pub mod actor;
#[path="config-fixture.rs"]mod config;
#[path="native-fixture.rs"]mod native;
use auto_tool::*;
use auto_tool::inventory::*;
#[cfg(test)]use serde_json::Value;
#[derive(Default)]struct RandomLow;
impl Random for RandomLow {fn int(&mut self,r:[i32;2])->Result<i32,String>{if r[0]>r[1]{Err("empty range".into())}else{Ok(r[0])}}fn float(&mut self)->f32{0.5}}
fn stacks()->Vec<ToolStack>{(0..36).map(|slot|ToolStack{slot,destroy_speed:1.,efficiency:0,silk_touch:0,max_damage:0,damage:0,empty:slot!=0,identity:format!("stack-{slot}")}).collect()}
fn mining()->MiningContext<'static>{MiningContext{position:[1,2,3],block:"minecraft:stone",tick:0,creative:false,sneaking:false,in_combat:false,bed_head_distances_squared:&[],serverside_slot:0}}
fn context(now:i64)->Context{Context{now,player_inventory:true,cursor_empty:true,menu_identity:"all menu slots+cursor".into(),requirements:RequirementState{rotation_matches:true,..Default::default()},..Default::default()}}
fn record(id:&str)->StackRecord{StackRecord{identity:id.into(),components:id.into(),count:1}}
fn snapshot(now:i64)->actor::Snapshot{actor::Snapshot{block:"minecraft:stone".into(),tick:0,creative:false,sneaking:false,server_slot:0,beds:vec![],stacks:stacks(),records:(0..36).map(|n|record(&format!("stack-{n}"))).collect(),context:context(now)}}
#[cfg(test)]mod tests {
use super::*;
#[test]fn default_tree_and_static_mode_apply_before_creative_filter(){let mut m=AutoTool::default();assert_eq!(m.tool_selector,ToolSelector::Dynamic);assert_eq!(m.constraints.start_delay,[50,100]);assert_eq!(m.swap_back_delay,20);let s=stacks();assert_eq!(m.progress(true,mining(),&s),Some(0));let mut c=mining();c.creative=true;assert_eq!(m.progress(true,c,&s),None);m.tool_selector=ToolSelector::Static;m.slot=8;assert_eq!(m.progress(true,c,&s),Some(8));assert_eq!(m.progress(false,c,&s),None);}
#[test]fn dynamic_durability_silk_filters_efficiency_and_hotbar_ties(){let mut m=AutoTool::default();let mut s=stacks();s[5].destroy_speed=8.;s[5].max_damage=100;s[5].damage=98;assert_eq!(m.progress(true,mining(),&s),Some(0));m.ignore_durability=true;assert_eq!(m.progress(true,mining(),&s),Some(5));m.ignore_durability=false;s[5].damage=97;assert_eq!(m.progress(true,mining(),&s),Some(5));s[4].destroy_speed=2.;s[4].efficiency=3;assert_eq!(m.progress(true,mining(),&s),Some(4));let mut c=mining();c.block="minecraft:glowstone";m.silk_touch_handler=true;assert_eq!(m.progress(true,c,&s),None);s[5].silk_touch=1;assert_eq!(m.progress(true,c,&s),Some(5));m.silk_touch_filter=Filter::Blacklist;assert_eq!(m.progress(true,c,&s),Some(4));m.silk_touch_handler=false;s[4].efficiency=0;s[4].destroy_speed=8.;c.serverside_slot=3;assert_eq!(m.progress(true,c,&s),Some(4));c.serverside_slot=5;assert_eq!(m.progress(true,c,&s),Some(5));}
#[test]fn exact_efficiency_int_overflow_matches_actual_jvm_oracle(){let v:Value=serde_json::from_str(include_str!("oracle.json")).unwrap();for row in v["efficiency"].as_array().unwrap(){let mut s=stacks().remove(0);s.destroy_speed=2.;s.efficiency=row["level"].as_i64().unwrap() as i32;assert_eq!(s.mining_speed(),row["speed"].as_f64().unwrap() as f32,"{row}");}}
#[test]fn java_float_nan_signed_zero_and_first_inventory_ties(){let mut m={let mut m=AutoTool::default();m.consider_inventory=true;m};let mut s=stacks();for x in &mut s{x.destroy_speed= -0.;}s[1].destroy_speed=0.;assert_eq!(m.progress(true,mining(),&s),Some(1));s[11].destroy_speed=f32::NAN;s[12].destroy_speed=f32::NAN;assert_eq!(m.progress(true,mining(),&s),None);assert_eq!(m.swaps.requested,Some(11));}
#[test]fn switch_delay_filter_stale_request_and_runtime_guards(){let mut m={let mut m=AutoTool::default();m.consider_inventory=true;m.switch_delay=2;m};let mut s=stacks();s[12].destroy_speed=5.;let mut c=mining();assert_eq!(m.progress(true,c,&s),None);c.tick=1;assert_eq!(m.progress(true,c,&s),None);assert_eq!(m.swaps.requested,None);c.tick=2;m.progress(true,c,&s);assert_eq!(m.swaps.requested,Some(12));m.filter=Filter::Whitelist;assert_eq!(m.progress(true,c,&s),None);assert_eq!(m.swaps.requested,Some(12));c.position=[9;3];c.in_combat=true;m.not_during_combat=true;m.progress(true,c,&s);assert_eq!(m.swaps.requested,Some(12));c.tick=4;m.progress(true,c,&s);assert_eq!(m.swaps.requested,None);m.disable();c.tick=5;m.filter=Filter::Blacklist;m.not_during_combat=false;m.progress(true,c,&s);assert_eq!(m.swaps.requested,None);c.tick=7;m.progress(true,c,&s);assert_eq!(m.swaps.requested,Some(12));m.cancel_breaking(true);assert_eq!(m.swaps.requested,None);}
#[test]fn sneaking_combat_and_bed_distance_boundary(){let mut m={let mut m=AutoTool::default();m.require_sneaking=true;m.not_during_combat=true;m.require_near_bed=true;m};let s=stacks();let mut c=mining();c.sneaking=true;c.bed_head_distances_squared=&[100.];assert_eq!(m.progress(true,c,&s),Some(0));c.bed_head_distances_squared=&[100.0000001];assert_eq!(m.progress(true,c,&s),None);c.bed_head_distances_squared=&[100.];c.in_combat=true;assert_eq!(m.progress(true,c,&s),None);c.in_combat=false;c.sneaking=false;assert_eq!(m.progress(true,c,&s),None);}
#[test]fn inventory_anchor_retains_first_action_and_restores_strictly_after_delay(){let s=stacks();let mut c=AnchoredSwapController::default();c.request(12);let p=c.tick(&s,0,2).unwrap();assert_eq!(p.action,SwapAction{source:12,hotbar:1});assert!(c.guards_hold(&s,2));c.performed(true);c.request(20);assert_eq!(c.tick(&s,7,2).unwrap().action,SwapAction{source:20,hotbar:1});c.performed(true);assert_eq!(c.anchor_action,Some(SwapAction{source:12,hotbar:1}));assert!(c.tick(&s,0,2).is_none());assert!(c.tick(&s,0,2).is_none());let restore=c.tick(&s,0,2).unwrap();assert!(restore.restoring);assert_eq!(restore.action.source,12);c.request(21);assert!(!c.guards_hold(&s,2));c.cancel_plan();c.reset();assert_eq!(c,AnchoredSwapController::default());}
#[test]fn inventory_plan_withdrawal_and_full_stack_identity_cancel(){let mut s=stacks();let mut c=AnchoredSwapController::default();c.request(12);c.tick(&s,0,20);c.clear_requested();assert!(!c.guards_hold(&s,20));c.request(12);s[2].identity="changed component".into();assert!(!c.guards_hold(&s,20));c.cancel_plan();c.tick(&s,0,20);assert!(c.guards_hold(&s,20));c.performed(false);assert!(c.anchor_action.is_none());}
#[test]fn all_inventory_requirements_use_original_thresholds(){let mut c=InventoryConstraints{requirements:31,..Default::default()};let mut r=RequirementState{rotation_matches:true,..Default::default()};assert!(c.passes(r));for i in 0..5{let mut bad=r;match i{0=>bad.jumping=true,1=>bad.rotation_matches=false,2=>bad.using_item=true,3=>bad.breaking=true,_=>bad.in_combat=true}assert!(!c.passes(bad));}c.requirements=1;r.movement=[0.003,0.];assert!(c.passes(r));r.movement=[0.004,0.];assert!(!c.passes(r));}
#[test]fn inventory_executor_uses_milliseconds_and_samples_close_after_click_delay(){let constraints=InventoryConstraints{start_delay:[50;2],click_delay:[100;2],close_delay:[70;2],slot_multiplier:0.,..Default::default()};let mut e=Executor::default();e.submit(SwapAction{source:9,hotbar:0},&context(0));let mut r=RandomLow;assert_eq!(e.frame(&context(0),&constraints,true,&mut r).unwrap(),None);assert_eq!(e.frame(&context(49),&constraints,true,&mut r).unwrap(),None);assert_eq!(e.frame(&context(50),&constraints,true,&mut r).unwrap(),Some(Operation::Swap(SwapAction{source:9,hotbar:0})));e.performed(&context(50),&constraints,record("tool"),true,&mut r).unwrap();assert_eq!(e.frame(&context(149),&constraints,true,&mut r).unwrap(),None);assert_eq!(e.frame(&context(150),&constraints,true,&mut r).unwrap(),None);assert_eq!(e.frame(&context(219),&constraints,true,&mut r).unwrap(),None);assert_eq!(e.frame(&context(220),&constraints,true,&mut r).unwrap(),Some(Operation::Close));assert!(!e.inventory_open_server_side);}
#[test]fn pending_inventory_guards_and_wait_windows_cancel_or_block(){let c=InventoryConstraints{start_delay:[0;2],slot_multiplier:0.,..Default::default()};let mut e=Executor::default();e.may_open_container(0);e.submit(SwapAction{source:9,hotbar:0},&context(0));assert_eq!(e.frame(&context(399),&c,true,&mut RandomLow).unwrap(),None);assert!(matches!(e.frame(&context(400),&c,true,&mut RandomLow).unwrap(),Some(Operation::Swap(_))));let mut x=context(401);x.menu_identity="armor changed".into();assert_eq!(e.frame(&x,&c,true,&mut RandomLow).unwrap(),None);assert!(!e.active());for flag in 0..3{let mut e=Executor::default();let mut x=context(0);match flag{0=>x.server_controlled=true,1=>x.player_inventory=false,_=>x.cursor_empty=false}assert!(!e.can_perform(&x,&c));e.submit(SwapAction{source:9,hotbar:0},&x);assert_eq!(e.frame(&x,&c,true,&mut RandomLow).unwrap(),None);}}
#[test]fn rejection_wait_count_lock_and_movement_exclusion(){for moving in [false,true]{let mut e=Executor::default();let c=InventoryConstraints{click_delay:[0;2],close_delay:[0;2],..Default::default()};for iteration in 0..3{let now=iteration*1000;let mut x=context(now);if moving{x.requirements.jumping=true;}e.submit(SwapAction{source:9,hotbar:0},&x);e.performed(&x,&c,record("item"),true,&mut RandomLow).unwrap();e.resync(9,&record("item"),now+10);assert!(!e.can_perform(&context(now+409),&c));e.poll(now+410);assert!(!e.can_perform(&context(now+809),&c));e.poll(now+810);}assert_eq!(e.locked_count(),usize::from(!moving));assert_eq!(e.is_locked(&record("item")),!moving);e.world_change();assert_eq!(e.locked_count(),0);}}
#[test]fn visible_cursor_travel_uses_cubic_interpolation(){let mut e=Executor::default();let c=InventoryConstraints{start_delay:[100;2],slot_multiplier:1.,..Default::default()};let mut x=context(0);x.inventory_screen=true;x.inventory_open=true;x.visible_cursor=Some([0.,0.]);e.submit(SwapAction{source:9,hotbar:0},&x);assert!(matches!(e.frame(&x,&c,true,&mut RandomLow).unwrap(),Some(Operation::MoveCursor(_))));x.now=100;let Some(Operation::MoveCursor(position))=e.frame(&x,&c,true,&mut RandomLow).unwrap()else{panic!("expected visible cursor travel")};assert!(position[0]>0.&&position[0]<16.&&position[1]>0.&&position[1]<92.);x.now=1000;assert!(matches!(e.frame(&x,&c,true,&mut RandomLow).unwrap(),Some(Operation::Swap(_))));}
#[test]fn actor_guard_includes_full_menu_and_server_locked_count(){let mut a=actor::InventoryActor::default();let mut m={let mut m=AutoTool::default();m.consider_inventory=true;m.constraints.start_delay=[0;2];m.constraints.slot_multiplier=0.;m};let mut s=snapshot(0);m.swaps.request(12);a.tick(&mut m,true,&s,false);assert!(matches!(a.frame(&mut m,true,&s,false,&mut RandomLow).unwrap(),Some(Operation::Swap(_))));a.performed(&mut m,&s,false,12,true,&mut RandomLow).unwrap();assert_eq!(m.swaps.anchor_hotbar,Some(1));s.context.now=200;m.swaps.request(13);a.tick(&mut m,true,&s,false);s.context.menu_identity="carried changed".into();assert_eq!(a.frame(&mut m,true,&s,false,&mut RandomLow).unwrap(),None);assert!(!a.executor.active());a.cancel_child(&mut m);assert!(m.swaps.anchor_action.is_none());}
#[test]fn actor_json_decoder_and_observation_reject_malformed_data(){let mut a=actor::InventoryActor::default();assert!(actor::Snapshot::parse("null").unwrap().is_none());assert!(actor::Snapshot::parse("{}").is_err());a.observe("{\"kind\":\"click\"}",0).unwrap();assert!(a.executor.inventory_open_server_side);a.observe("{\"kind\":\"close\"}",0).unwrap();assert!(!a.executor.inventory_open_server_side);assert!(a.observe("{\"kind\":\"unknown\"}",0).is_err());}
#[test]fn silent_hotbar_cosmetic_does_not_require_slot_modified(){let mut slot=5;let mut scale=0.2;let m=silent_hotbar_render::SilentHotbarRender::default();m.render(true,true,2,&mut slot,&mut scale);assert_eq!((slot,scale),(2,1.));scale=0.3;m.render(true,false,3,&mut slot,&mut scale);assert_eq!((slot,scale),(3,0.3));m.render(false,true,7,&mut slot,&mut scale);assert_eq!((slot,scale),(3,0.3));}
#[test]fn inventory_open_screen_does_not_complete_server_container_wait(){let mut e=Executor::default();let c=InventoryConstraints::default();e.may_open_container(0);e.opened();assert!(!e.can_perform(&context(399),&c));e.container_opened();assert!(e.can_perform(&context(399),&c));}
#[test]fn content_resync_missing_source_slot_clears_unjudged_click(){let mut e=Executor::default();let c=InventoryConstraints{click_delay:[0;2],close_delay:[0;2],..Default::default()};e.submit(SwapAction{source:9,hotbar:0},&context(0));e.performed(&context(0),&c,record("tool"),true,&mut RandomLow).unwrap();e.resync_content(&[],10);e.poll(800);assert_eq!(e.locked_count(),0);assert!(e.can_perform(&context(800),&c));}
#[test]fn cursor_origin_and_all_inventory_slot_positions_match_actual_minecraft_menu(){let v:Value=serde_json::from_str(include_str!("oracle.json")).unwrap();let center=&v["inventoryMenuCenter"];assert_eq!(Executor::menu_center(),[center[0].as_f64().unwrap() as f32,center[1].as_f64().unwrap() as f32]);let slots=v["inventoryMenuSlots"].as_array().unwrap();assert_eq!(slots.len(),46);for slot in 0..36{let id=if slot<9{slot+36}else{slot};let expected=&slots[id];assert_eq!(Executor::slot_position(slot as u8),[expected[0].as_f64().unwrap() as f32,expected[1].as_f64().unwrap() as f32],"{slot}");}}
#[test]fn chained_close_delays_accumulate_and_new_request_waits_for_started_pause(){let mut e=Executor::default();let mut c=InventoryConstraints{start_delay:[0;2],click_delay:[100;2],close_delay:[70;2],slot_multiplier:0.,..Default::default()};let action=SwapAction{source:9,hotbar:0};e.submit(action,&context(0));assert_eq!(e.frame(&context(0),&c,true,&mut RandomLow).unwrap(),Some(Operation::Swap(action)));e.performed(&context(0),&c,record("first"),true,&mut RandomLow).unwrap();e.submit(action,&context(50));c.close_delay=[10;2];assert_eq!(e.frame(&context(100),&c,true,&mut RandomLow).unwrap(),Some(Operation::Swap(action)));e.performed(&context(100),&c,record("second"),true,&mut RandomLow).unwrap();assert_eq!(e.frame(&context(200),&c,true,&mut RandomLow).unwrap(),None);e.submit(action,&context(220));assert_eq!(e.frame(&context(269),&c,true,&mut RandomLow).unwrap(),None);assert_eq!(e.frame(&context(270),&c,true,&mut RandomLow).unwrap(),Some(Operation::Swap(action)));}
}
